%% Extracción de datos

t  = D2(:,2) * 1e-6;     % s
I  = D2(:,4) / 1000;     % A
Vm = D2(:,6) / 1000;     % V

% Si aún no existen ángulo/omega, rellena con NaN
if size(D2,2) >= 8
    ang = D2(:,7);       % deg
    omg = D2(:,8);       % rad/s
else
    ang = nan(size(t));
    omg = nan(size(t));
end

% %% Cálculo de la velocidad angular
% 
% dt = 100e-6;            % 100 us
% theta = theta(:);       % columna
% 
% % 1) grados -> radianes
% theta_rad = deg2rad(ang);
% 
% % 2) quitar saltos por wrap (0-2pi)
% theta_u = unwrap(theta_rad);  % asume saltos > pi son wrap
% 
% % 3) derivada (misma longitud que theta)
% omega_signed = gradient(theta_u, dt);   % [rad/s]
% 
% % 4) magnitud (si la quieres siempre positiva)
% omega = abs(omega_signed);
% omega(1) = 0;  % si quieres forzar inicio en 0
% 
% % 5) suavizado simple (ej: ventana de 1 ms)
% N = round(1e-3/dt);     % 1 ms -> 10 muestras (con dt=100us)
% omega_f = movmean(omega, N);

%%
dt = 500e-6;
theta = unwrap(deg2rad(ang));  % si ya tienes theta en grados

N = 10; % 10 muestras -> ventana 5 ms
omega = zeros(size(theta));
omega(N+1:end) = abs((theta(N+1:end) - theta(1:end-N)) / (N*dt));
%%
dt = 1e-4;                 % 100 us
theta = unwrap(deg2rad(ang));

theta_s = sgolayfilt(theta, 3, 41);   % orden 3, ventana 41 (ajusta)
omega_f  = gradient(theta_s, dt);
%% ===== Figuras =====
figure('Color','w');
tiledlayout(2,2,'Padding','compact','TileSpacing','compact');

figure(1)
plot(t,Vm, 'LineWidth', 1.2)
xlabel('tiempo $[s]$','Interpreter','latex')
ylabel('Voltaje $[V]$','Interpreter','latex')
title('Gráfica de voltaje del motor')
set(gca,'TickLabelInterpreter', 'latex');
grid on

figure(2)
plot(t, I, 'LineWidth', 1.2)
xlabel('Tiempo $[s]$','Interpreter','latex')
ylabel('Corriente $[A]$','Interpreter','latex')
title('Gráfica de corriente')
set(gca,'TickLabelInterpreter', 'latex');
grid on
exportgraphics(gcf,'mediciones_corriente_motor_force_latex.pdf','ContentType','vector');
exportgraphics(gcf,'mediciones_corriente_motor_latex.png','Resolution',300);
figure(3)
subplot 121
plot(t, ang, 'LineWidth', 1.2)
xlabel('tiempo $[s]$','Interpreter','latex')
ylabel('$\theta$','Interpreter','latex')
title('Gráfica de posición angular')
set(gca,'TickLabelInterpreter', 'latex');
grid on

subplot 122
plot(t, omg, 'LineWidth', 1.2)
xlabel('tiempo $[s]$','Interpreter','latex')
ylabel('$\omega [rad/s]$','Interpreter','latex')
title('Gráfica de velocidad angular')
set(gca,'TickLabelInterpreter', 'latex');
grid on
